#include "TestSupport.h"
#include "../src/Shop/ShopPresentationState.h"
#include <variant>
int main(){ TestContext t; ShopPresentationState s; ShopOpenedEvent e{4,1,NpcType::DEVELOPMENT_GUIDE,77,ShopId::DEVELOPMENT_GUIDE_SUPPLIES,"Supplies",ItemType::COINS,{{ItemType::COOKED_MEAT,8,3}}}; ActiveShopSession a{77,4,1,NpcType::DEVELOPMENT_GUIDE,ShopId::DEVELOPMENT_GUIDE_SUPPLIES,1}; s.Synchronize(4,{e},&a); t.Expect(s.IsOpen(),"Matching identity opens shop"); auto b=s.MakeBuy(0); auto* buy=b?std::get_if<ShopBuyCommand>(&*b):nullptr; t.Expect(buy&&buy->shopSessionId==77&&buy->itemType==ItemType::COOKED_MEAT,"Buy preserves identity"); ActiveShopSession mismatch=a; mismatch.npcEntityID=9; s.Synchronize(4,{e},&mismatch); t.Expect(!s.IsOpen(),"NPC mismatch clears shop"); s.Synchronize(4,{e},&a); ShopOpenedEvent bad=e; bad.shopId=ShopId::DEVELOPMENT_GUIDE_SUPPLIES; mismatch=a; mismatch.sessionId=78; bad.sessionId=78; s.Synchronize(4,{bad},&mismatch); t.Expect(!s.IsOpen(),"Session mismatch is rejected"); s.Synchronize(4,{e},&a); s.Dismiss(); s.Synchronize(4,{e},&a); t.Expect(!s.IsOpen(),"Dismissed session stays closed"); s.Synchronize(4,{},nullptr); t.Expect(!s.MakeSell(0).has_value()&&!s.MakeClose().has_value(),"Stale commands are rejected"); return t.Finish(); }
